// Package attach: validation and normalization of attachments (images, GIFs, videos).
//
// Security rule: file type is determined EXCLUSIVELY from magic bytes
// (net/http.DetectContentType), never from file name or field sent by peer.
// File name is stripped from path and assigned an extension
// matching the detected type — a "photo.png" file containing HTML or
// script will fail validation, and "x.png.sh" will not be saved as .sh.
//
// Avatar goes one step further: fully decoded and RE-ENCODED with our
// encoder (PNG or GIF), ensuring database gets bytes generated by us
// instead of user input. Appended payloads (polyglot ZIP/HTML/JS,
// EXIF, comments, ICC profiles) simply do not survive this operation.
package attach

import (
	"bytes"
	"errors"
	"fmt"
	"image"
	"image/color/palette"
	"image/draw"
	"image/gif"
	"image/jpeg" // thumbnail encoder; import registers JPEG decoder
	"image/png"
	"net/http"
	"path/filepath"
	"strings"
	"time"

	xdraw "golang.org/x/image/draw"
	_ "golang.org/x/image/webp"
)

const (
	// MaxFileBytes: attachment ceiling in chat. Blob goes over ctrl channel
	// and lands in bbolt as a single value — hence reasonable size cap.
	// If anyone hits limit, implement file streaming to disk.
	MaxFileBytes = 32 << 20
	// PreviewMax: above this size we do not replicate full file. Sender
	// generates thumbnail, sent to everyone immediately, while full bytes travel
	// on demand (and only when someone holding them is online).
	PreviewMax = 10 << 20
	// PreviewSide: maximum side length of thumbnail.
	PreviewSide = 720
	// MaxAvatarBytes: limit for user selection from disk.
	MaxAvatarBytes = 4 << 20
	// MaxAvatarOut: limit after normalization (replicated size).
	MaxAvatarOut = 1 << 20
	// AvatarSide: avatar is square, center-cropped.
	AvatarSide = 256
	// BannerW/BannerH: profile banner is a wide strip, center-cropped.
	BannerW, BannerH = 720, 240

	maxGifFrames = 300
	maxDim       = 8000
	maxPixels    = 20_000_000 // ~80 MB RGBA at peak — decompression bomb guard
	sniffLen     = 512
)

// Meta: attachment metadata after validation (stored in DAG event).
type Meta struct {
	Name string
	Mime string
	Size int64
	W, H int
}

var (
	imageMimes = map[string]string{
		"image/png":  ".png",
		"image/jpeg": ".jpg",
		"image/gif":  ".gif",
		"image/webp": ".webp",
	}
	// Video is container-only: we don't have a decoder, so we don't pretend
	// to validate contents. Security relies on file never being executed, with name
	// and extension enforced by us.
	// Mkv shares EBML structure with webm and detects as video/webm — which is fine.
	videoMimes = map[string]string{
		"video/mp4":  ".mp4",
		"video/webm": ".webm",
	}
)

func IsImage(mime string) bool { _, ok := imageMimes[mime]; return ok }
func IsVideo(mime string) bool { _, ok := videoMimes[mime]; return ok }

// IsMedia: types we render directly or pass to media player. Everything else
// is "generic file" — rendered as tile and downloadable to disk.
func IsMedia(mime string) bool { return IsImage(mime) || IsVideo(mime) }

// Animated: whether type supports animation (GIF) — UI triggers frame player.
func Animated(mime string) bool { return mime == "image/gif" }

// Ext returns extension forced by detected type ("" for unknown).
func Ext(mime string) string {
	if e, ok := imageMimes[mime]; ok {
		return e
	}
	return videoMimes[mime]
}

// SniffAny detects type from magic bytes — without whitelist. Network filename
// never determines type or extension of saved file.
func SniffAny(data []byte) string {
	head := data
	if len(head) > sniffLen {
		head = head[:sniffLen]
	}
	mime := http.DetectContentType(head)
	if i := strings.IndexByte(mime, ';'); i >= 0 { // "text/plain; charset=utf-8"
		mime = mime[:i]
	}
	return mime
}

// Sniff returns type only for supported renderable media (image/video);
// returns "" for everything else. Use where rendering matters, not saving.
func Sniff(data []byte) string {
	if mime := SniffAny(data); IsMedia(mime) {
		return mime
	}
	return ""
}

// SafeName: safe filename for UI display and disk storage. Strips directories,
// control characters, separators, and truncates length.
//
// Extension: forced by detected type for media (a "photo.png" script
// will not be saved as .sh). For generic files, extension from name is kept —
// otherwise PDF or ZIP could not be opened — but we filter to alphanumeric
// characters and allow exactly one dot, so "report.pdf.exe" cannot pretend to be PDF.
// We never execute files automatically.
func SafeName(name, mime string) string {
	name = filepath.Base(strings.ReplaceAll(strings.TrimSpace(name), `\`, "/"))
	name = strings.Map(func(r rune) rune {
		switch {
		case r < 0x20 || r == 0x7f: // control characters
			return -1
		case strings.ContainsRune(`/:*?"<>|`, r):
			return '_'
		}
		return r
	}, name)
	name = strings.TrimLeft(name, ".") // ".bashrc", "..", hidden files
	ext := Ext(mime)
	if i := strings.LastIndexByte(name, '.'); i > 0 {
		if ext == "" {
			ext = cleanExt(name[i+1:])
			if mediaExt(ext) {
				// content is not media (otherwise Ext would name it), so filename
				// won't fake it — HTML won't save as .png
				ext = ""
			}
		}
		name = name[:i]
	}
	name = strings.ReplaceAll(name, ".", "_") // eliminate double extensions
	if name == "" {
		name = "zalacznik"
	}
	if len(name) > 60 {
		name = name[:60]
	}
	if ext == "" {
		ext = ".bin"
	}
	return name + ext
}

// mediaExt: extension that our UI would treat as image or video.
func mediaExt(ext string) bool {
	for _, m := range []map[string]string{imageMimes, videoMimes} {
		for _, e := range m {
			if e == ext {
				return true
			}
		}
	}
	return ext == ".jpeg" // single alias missing from lookup tables
}

// cleanExt: extension for generic file — alphanumeric characters only, up to 10 chars.
func cleanExt(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
		if b.Len() >= 10 {
			break
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return "." + b.String()
}

// Check validates attachment before sending: size cap, type from magic
// bytes, and full decode for images (verifying image integrity).
// Non-media files pass without inspecting content — we don't claim to
// validate PDF or archive; we never execute them.
func Check(data []byte, name string) (Meta, error) {
	if len(data) == 0 {
		return Meta{}, errors.New("pusty plik")
	}
	if len(data) > MaxFileBytes {
		return Meta{}, fmt.Errorf("plik ma %s — limit to %s",
			HumanSize(int64(len(data))), HumanSize(MaxFileBytes))
	}
	mime := SniffAny(data)
	m := Meta{Name: SafeName(name, mime), Mime: mime, Size: int64(len(data))}
	if !IsImage(mime) {
		return m, nil
	}
	_, w, h, err := imageDims(data)
	if err != nil {
		return Meta{}, err
	}
	m.W, m.H = w, h
	// full decode on sender side: corrupted or forged image
	// surfaces here, not on receiver side
	if _, _, err := image.Decode(bytes.NewReader(data)); err != nil {
		return Meta{}, fmt.Errorf("to nie jest poprawny obraz: %w", err)
	}
	return m, nil
}

// Verify validates blob received from peer: type must match
// signed event claim, and image must have valid header.
// Full decode is omitted here — UI does it anyway during rendering, and
// forcing it on every incoming file creates an unneeded CPU vector.
func Verify(data []byte, mime string) error {
	if len(data) == 0 || len(data) > MaxFileBytes {
		return errors.New("blob poza limitem")
	}
	if got := SniffAny(data); got != mime {
		return fmt.Errorf("typ nie zgadza się z zapowiedzianym (%q vs %q)", got, mime)
	}
	if IsImage(mime) {
		if _, _, _, err := imageDims(data); err != nil {
			return err
		}
	}
	return nil
}

// CheckDims validates dimension limits from header without full decoding —
// for bytes bypassing Check/Verify (e.g. video call frames).
func CheckDims(data []byte) error {
	_, _, _, err := imageDims(data)
	return err
}

// imageDims reads image header and checks size limits (decompression bomb guard).
func imageDims(data []byte) (format string, w, h int, err error) {
	cfg, format, err := image.DecodeConfig(bytes.NewReader(data))
	if err != nil {
		return "", 0, 0, fmt.Errorf("nieczytelny nagłówek obrazu: %w", err)
	}
	if cfg.Width <= 0 || cfg.Height <= 0 || cfg.Width > maxDim || cfg.Height > maxDim ||
		cfg.Width*cfg.Height > maxPixels {
		return "", 0, 0, fmt.Errorf("obraz %dx%d poza limitem (max %d px na bok, %d MPx)",
			cfg.Width, cfg.Height, maxDim, maxPixels/1_000_000)
	}
	return format, cfg.Width, cfg.Height, nil
}

// Preview creates thumbnail of large image: max side PreviewSide px, JPEG.
// Replicated to all peers when file exceeds PreviewMax.
// Returns error for non-images — video without decoder cannot be previewed,
// and pulling ffmpeg into chat client is significant bloat.
func Preview(data []byte, mime string) (out []byte, w, h int, err error) {
	if !IsImage(mime) {
		return nil, 0, 0, errors.New("podgląd tylko dla obrazów")
	}
	if _, _, _, err := imageDims(data); err != nil {
		return nil, 0, 0, err
	}
	src, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, 0, 0, err
	}
	b := src.Bounds()
	w, h = b.Dx(), b.Dy()
	if w > PreviewSide || h > PreviewSide {
		if w >= h {
			h, w = h*PreviewSide/w, PreviewSide
		} else {
			w, h = w*PreviewSide/h, PreviewSide
		}
	}
	if w < 1 || h < 1 {
		return nil, 0, 0, errors.New("obraz bez wymiarów")
	}
	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	xdraw.CatmullRom.Scale(dst, dst.Bounds(), src, b, xdraw.Over, nil)
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, dst, &jpeg.Options{Quality: 78}); err != nil {
		return nil, 0, 0, err
	}
	return buf.Bytes(), w, h, nil
}

// Avatar normalizes image into avatar: square AvatarSide px, re-encoded
// using our encoder. GIF stays GIF (preserving animation), others output
// as PNG. Returns resulting bytes and mime type.
func Avatar(data []byte) ([]byte, string, error) {
	if len(data) == 0 {
		return nil, "", errors.New("pusty plik")
	}
	if len(data) > MaxAvatarBytes {
		return nil, "", fmt.Errorf("awatar ma %s — limit to %s",
			HumanSize(int64(len(data))), HumanSize(MaxAvatarBytes))
	}
	mime := Sniff(data)
	if !IsImage(mime) {
		return nil, "", errors.New("awatar musi być obrazem: PNG, JPEG, GIF albo WebP")
	}
	if _, _, _, err := imageDims(data); err != nil {
		return nil, "", err
	}
	if mime == "image/gif" {
		return avatarGIF(data)
	}
	src, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, "", fmt.Errorf("to nie jest poprawny obraz: %w", err)
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, square(src, AvatarSide)); err != nil {
		return nil, "", err
	}
	if buf.Len() > MaxAvatarOut {
		return nil, "", errors.New("awatar po przeskalowaniu wciąż za duży — użyj prostszego obrazka")
	}
	return buf.Bytes(), "image/png", nil
}

// Banner normalizes image into a profile banner: BannerW×BannerH strip,
// re-encoded as PNG.
// Banner is a still — an animated GIF keeps its first frame only.
func Banner(data []byte) ([]byte, string, error) {
	if len(data) == 0 {
		return nil, "", errors.New("pusty plik")
	}
	if len(data) > MaxAvatarBytes {
		return nil, "", fmt.Errorf("baner ma %s — limit to %s",
			HumanSize(int64(len(data))), HumanSize(MaxAvatarBytes))
	}
	if !IsImage(Sniff(data)) {
		return nil, "", errors.New("baner musi być obrazem: PNG, JPEG, GIF albo WebP")
	}
	if _, _, _, err := imageDims(data); err != nil {
		return nil, "", err
	}
	src, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, "", fmt.Errorf("to nie jest poprawny obraz: %w", err)
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, cropScale(src, BannerW, BannerH)); err != nil {
		return nil, "", err
	}
	if buf.Len() > MaxAvatarOut {
		return nil, "", errors.New("baner po przeskalowaniu wciąż za duży — użyj prostszego obrazka")
	}
	return buf.Bytes(), "image/png", nil
}

// avatarGIF: decodes all frames, compositing diffs (GIF stores diffs, not
// full images), scales and re-encodes. If output exceeds limit,
// drops every second frame and retries.
func avatarGIF(data []byte) ([]byte, string, error) {
	frames, delays, err := GifFrames(data)
	if err != nil {
		return nil, "", err
	}
	for {
		g := &gif.GIF{LoopCount: 0}
		for i, fr := range frames {
			pal := image.NewPaletted(image.Rect(0, 0, AvatarSide, AvatarSide), palette.Plan9)
			draw.FloydSteinberg.Draw(pal, pal.Bounds(), square(fr, AvatarSide), image.Point{})
			g.Image = append(g.Image, pal)
			d := int(delays[i] / (10 * time.Millisecond))
			if d < 2 {
				d = 2 // < 20 ms is effectively "as fast as possible"
			}
			g.Delay = append(g.Delay, d)
			g.Disposal = append(g.Disposal, gif.DisposalNone)
		}
		var buf bytes.Buffer
		if err := gif.EncodeAll(&buf, g); err != nil {
			return nil, "", err
		}
		if buf.Len() <= MaxAvatarOut {
			return buf.Bytes(), "image/gif", nil
		}
		if len(frames) <= 1 {
			return nil, "", errors.New("animowany awatar za duży — użyj krótszego GIF-a")
		}
		frames, delays = decimate(frames, delays)
	}
}

// decimate retains every second frame, summing display delays.
func decimate(frames []image.Image, delays []time.Duration) ([]image.Image, []time.Duration) {
	var of []image.Image
	var od []time.Duration
	for i := 0; i < len(frames); i += 2 {
		d := delays[i]
		if i+1 < len(delays) {
			d += delays[i+1]
		}
		of = append(of, frames[i])
		od = append(od, d)
	}
	return of, od
}

// square crops image to center square and scales to side px.
func square(src image.Image, side int) image.Image { return cropScale(src, side, side) }

// cropScale: center-crop to the target aspect ratio, then scale to w×h.
func cropScale(src image.Image, w, h int) image.Image {
	b := src.Bounds()
	cw, chh := b.Dx(), b.Dy()
	if cw*h > chh*w { // source wider than target — trim the sides
		cw = chh * w / h
	} else {
		chh = cw * h / w
	}
	crop := image.Rect(0, 0, cw, chh).Add(image.Point{
		X: b.Min.X + (b.Dx()-cw)/2,
		Y: b.Min.Y + (b.Dy()-chh)/2,
	})
	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	xdraw.CatmullRom.Scale(dst, dst.Bounds(), src, crop, xdraw.Over, nil)
	return dst
}

// GifFrames decodes GIF into list of ready-to-display frames.
// Composites them honoring Disposal field — raw frames from gif.DecodeAll
// are often partial frame patches.
func GifFrames(data []byte) ([]image.Image, []time.Duration, error) {
	g, err := gif.DecodeAll(bytes.NewReader(data))
	if err != nil {
		return nil, nil, fmt.Errorf("uszkodzony GIF: %w", err)
	}
	if len(g.Image) == 0 {
		return nil, nil, errors.New("GIF bez klatek")
	}
	if len(g.Image) > maxGifFrames {
		return nil, nil, fmt.Errorf("GIF ma %d klatek — limit to %d", len(g.Image), maxGifFrames)
	}
	if g.Config.Width <= 0 || g.Config.Height <= 0 ||
		g.Config.Width*g.Config.Height*len(g.Image) > maxPixels {
		return nil, nil, errors.New("GIF poza limitem rozmiaru")
	}
	rect := image.Rect(0, 0, g.Config.Width, g.Config.Height)
	cur := image.NewRGBA(rect)
	var out []image.Image
	var delays []time.Duration
	for i, fr := range g.Image {
		var backup *image.RGBA
		if i < len(g.Disposal) && g.Disposal[i] == gif.DisposalPrevious {
			backup = image.NewRGBA(rect)
			draw.Draw(backup, rect, cur, rect.Min, draw.Src)
		}
		draw.Draw(cur, fr.Bounds(), fr, fr.Bounds().Min, draw.Over)
		snap := image.NewRGBA(rect)
		draw.Draw(snap, rect, cur, rect.Min, draw.Src)
		out = append(out, snap)
		d := 100 * time.Millisecond
		if i < len(g.Delay) && g.Delay[i] > 0 {
			d = time.Duration(g.Delay[i]) * 10 * time.Millisecond
		}
		delays = append(delays, d)
		if i < len(g.Disposal) {
			switch g.Disposal[i] {
			case gif.DisposalBackground:
				draw.Draw(cur, fr.Bounds(), image.Transparent, image.Point{}, draw.Src)
			case gif.DisposalPrevious:
				draw.Draw(cur, rect, backup, rect.Min, draw.Src)
			}
		}
	}
	return out, delays, nil
}

// HumanSize formats byte counts for UI display.
func HumanSize(n int64) string {
	switch {
	case n >= 1<<20:
		return fmt.Sprintf("%.1f MB", float64(n)/(1<<20))
	case n >= 1<<10:
		return fmt.Sprintf("%.0f kB", float64(n)/(1<<10))
	}
	return fmt.Sprintf("%d B", n)
}
